from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_border = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_border = True
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] == background and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            if not touches_border:
                ys = [y for y, _ in component]
                xs = [x for _, x in component]
                box_area = (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)
                if len(component) == box_area:
                    for y, x in component:
                        out[y][x] = 4
    return out

